package com.travelapp.customize.service;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.travelapp.common.*; import com.travelapp.customize.dto.*; import com.travelapp.customize.entity.*; import com.travelapp.customize.mapper.*; import com.travelapp.itinerary.service.ItineraryService; import com.fasterxml.jackson.databind.ObjectMapper; import lombok.RequiredArgsConstructor; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*; import java.util.stream.*;
@Service @RequiredArgsConstructor public class CustomizeServiceImpl implements CustomizeService { private final QaRuleMapper rules; private final CustomizeSessionMapper sessions; private final CustomizeAnswerMapper answers; private final CustomizeDestinationMapper destinations; private final StringRedisTemplate redis; private final ObjectMapper json; private final ItineraryService itineraryService; private static final String KEY="customize:session:";
 public List<?> questions(){ return rules.selectList(new LambdaQueryWrapper<QaRule>().eq(QaRule::getIsActive,true).orderByAsc(QaRule::getSortOrder)); }
 @Transactional public SessionResponseDTO create(Long uid, CreateSessionDTO r){ CustomizeSession s=new CustomizeSession(); s.setUserId(uid); s.setSourceNoteId(r.getSourceNoteId()); s.setStatus(0); sessions.insert(s); String t=UUID.randomUUID().toString(); redis.opsForValue().set(KEY+s.getId(),t,Duration.ofDays(7)); return out(s,t); }
 public SessionResponseDTO get(Long uid,Long id,String t){ CustomizeSession s=owned(uid,id,t); return out(s,null); }
 @Transactional public SessionResponseDTO save(Long uid,Long id,String t,SaveAnswersDTO r){ CustomizeSession s=owned(uid,id,t); CustomizeAnswer a=answers.selectOne(new LambdaQueryWrapper<CustomizeAnswer>().eq(CustomizeAnswer::getSessionId,id)); if(a==null){a=new CustomizeAnswer();a.setSessionId(id);} a.setDays(r.getDays());a.setDepartDate(r.getDepartDate());a.setReturnDate(r.getReturnDate());a.setDepartCity(r.getDepartCity());a.setHasBookedTransport(Boolean.TRUE.equals(r.getHasBookedTransport()));a.setBudgetMin(r.getBudgetMin());a.setBudgetMax(r.getBudgetMax());a.setTravelerCount(r.getTravelerCount());a.setTravelerComposition(r.getTravelerComposition());a.setTravelStyle(r.getTravelStyle()); try{a.setInterestTags(json.writeValueAsString(r.getInterestTagIds()));a.setExtraAnswers(json.writeValueAsString(r.getExtraAnswers()));}catch(Exception e){throw new BusinessException(ErrorCode.PARAM_INVALID,"Invalid Q&A format");} if(a.getId()==null)answers.insert(a);else answers.updateById(a); destinations.delete(new LambdaQueryWrapper<CustomizeDestination>().eq(CustomizeDestination::getSessionId,id)); List<DestinationInputDTO> inputs=r.getDestinations(); for(int i=0;i<inputs.size();i++){DestinationInputDTO in=inputs.get(i);CustomizeDestination d=new CustomizeDestination();d.setSessionId(id);d.setDestinationId(in.getId());d.setDestinationName(in.getName().trim());d.setSortOrder(i+1);destinations.insert(d);} return out(s,null); }
 @Transactional public CompleteResponseDTO complete(Long uid,Long id,String t){CustomizeSession s=owned(uid,id,t);s.setStatus(1);s.setCompletedAt(LocalDateTime.now());sessions.updateById(s);Long planId=itineraryService.requestGeneration(id,uid);return CompleteResponseDTO.builder().planId(planId).status("generating").build();}
 @Transactional public SessionResponseDTO bind(Long uid,Long id,String t){CustomizeSession s=sessions.selectById(id);if(s==null)throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND,"Customize session does not exist");if(s.getUserId()!=null){if(!s.getUserId().equals(uid))throw new BusinessException(ErrorCode.FORBIDDEN,"This session is already bound to another account");return out(s,null);}String x=redis.opsForValue().get(KEY+id);if(t==null||!t.equals(x))throw new BusinessException(ErrorCode.FORBIDDEN,"Not authorized to access this session");s.setUserId(uid);sessions.updateById(s);redis.delete(KEY+id);return out(s,null);}
 private CustomizeSession owned(Long uid,Long id,String t){CustomizeSession s=sessions.selectById(id);if(s==null)throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND,"Customize session does not exist");if(s.getUserId()!=null&&s.getUserId().equals(uid))return s;String x=redis.opsForValue().get(KEY+id);if(t!=null&&t.equals(x))return s;throw new BusinessException(ErrorCode.FORBIDDEN,"Not authorized to access this session");}
 private SessionResponseDTO out(CustomizeSession s,String t){List<DestinationInputDTO> refs=destinations.selectList(new LambdaQueryWrapper<CustomizeDestination>().eq(CustomizeDestination::getSessionId,s.getId()).orderByAsc(CustomizeDestination::getSortOrder)).stream().map(cd->{DestinationInputDTO dto=new DestinationInputDTO();dto.setId(cd.getDestinationId());dto.setName(cd.getDestinationName());return dto;}).collect(Collectors.toList());return SessionResponseDTO.builder().id(s.getId()).sessionToken(t).status(s.getStatus()).destinations(refs).createdAt(s.getCreatedAt()).build();}}
